package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.chart.*;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import org.brightstats.stats.*;
final class PcaPlots {
    private PcaPlots(){}
    static void add(TabPane tabs,PrincipalComponents.Fit fit,PcaRotation.Fit rotated,List<String> names){
        VBox plots=new VBox(12);plots.setPadding(new Insets(12));Label note=UiAppearance.label("Scree values describe unrotated PCA. Coordinate plots display the first two retained axes; they do not determine a statistically justified component count. Score plots show up to 5000 evenly spaced analysis rows; source links recover original row IDs. Full scores remain in the tables/archive. Covariance-PCA loading and pattern coefficients retain variable units. Oblique coordinates are correlated, and explained-variance percentages are not additive after promax.");note.setWrapText(true);plots.getChildren().add(note);
        NumberAxis x=new NumberAxis(),y=new NumberAxis();x.setLabel("Unrotated component rank");y.setLabel("Eigenvalue");LineChart<Number,Number> scree=new LineChart<>(x,y);scree.setTitle((fit.correlation()?"Correlation":"Covariance")+" PCA scree");scree.setAnimated(false);scree.setMinHeight(430);var eigen=new XYChart.Series<Number,Number>();eigen.setName("Unrotated eigenvalues");double[] values=fit.eigenvalues();for(int i=0;i<values.length;i++)eigen.getData().add(new XYChart.Data<>(i+1,values[i]));scree.getData().add(eigen);if(fit.correlation()){var reference=new XYChart.Series<Number,Number>();reference.setName("Eigenvalue one reference (not a significance threshold)");for(int i=0;i<values.length;i++)reference.getData().add(new XYChart.Data<>(i+1,1));scree.getData().add(reference);}plots.getChildren().add(scree);
        if(fit.retained()>=2){plots.getChildren().add(coefficients("Unrotated loading coordinates",fit.loadings(),names,"PC loading"));plots.getChildren().add(scores("Unrotated PCA scores",fit.scores(),"PC score"));if(rotated!=null){plots.getChildren().add(coefficients(rotated.options().method()+" pattern coordinates",rotated.pattern(),names,"Rotated pattern"));plots.getChildren().add(scores(rotated.options().method()+" unit-variance score coordinates",rotated.scores(),"Rotated unit score"));}}
        ScrollPane scroll=new ScrollPane(plots);scroll.setFitToWidth(true);Tab tab=new Tab("PCA graphics",scroll);tab.setClosable(false);tabs.getTabs().add(tab);
    }
    private static ScatterChart<Number,Number> chart(String title,String prefix){NumberAxis x=new NumberAxis(),y=new NumberAxis();x.setLabel(prefix+" 1");y.setLabel(prefix+" 2");ScatterChart<Number,Number> chart=new ScatterChart<>(x,y);chart.setTitle(title);chart.setAnimated(false);chart.setLegendVisible(false);chart.setMinHeight(430);return chart;}
    private static ScatterChart<Number,Number> coefficients(String title,double[][] values,List<String> names,String prefix){var chart=chart(title,prefix);chart.setLegendVisible(names.size()<=24);for(int row=0;row<values.length;row++){var series=new XYChart.Series<Number,Number>();String name=names.get(row);series.setName(name);var point=new XYChart.Data<Number,Number>(values[row][0],values[row][1],org.brightstats.report.GraphicPoint.original(name,List.of(),List.of(name)));point.nodeProperty().addListener((observable,old,node)->{if(node!=null)Tooltip.install(node,new Tooltip(name+": "+point.getXValue()+", "+point.getYValue()));});series.getData().add(point);chart.getData().add(series);}return chart;}
    private static ScatterChart<Number,Number> scores(String title,double[][] values,String prefix){var chart=chart(title,prefix);var series=new XYChart.Series<Number,Number>();series.setName(values.length>5000?"Evenly spaced analysis rows (display cap 5000)":"Analysis observation rows");int count=Math.min(5000,values.length);for(int i=0;i<count;i++){int row=count==1?0:(int)((long)i*(values.length-1)/(count-1));series.getData().add(new XYChart.Data<>(values[row][0],values[row][1],org.brightstats.report.GraphicPoint.analysis("Analysis row "+(row+1),row+1,List.of())));}chart.getData().add(series);return chart;}
}
